import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests


class FederatedLoginError(RuntimeError):
    pass


def _normalize_claims(claims: Dict[str, Any]) -> Dict[str, Any]:
    normalized = dict(claims)

    # Standardize common OIDC/federated fields
    if "sub" in normalized and "user_id" not in normalized:
        normalized["user_id"] = normalized["sub"]

    if "name" not in normalized:
        given = normalized.get("given_name", "")
        family = normalized.get("family_name", "")
        full_name = (given + " " + family).strip()
        if full_name:
            normalized["name"] = full_name

    if "email" in normalized:
        normalized["email"] = str(normalized["email"]).lower()

    if "groups" not in normalized:
        for candidate in ("roles", "permissions", "authorities"):
            if candidate in normalized and isinstance(normalized[candidate], list):
                normalized["groups"] = normalized[candidate]
                break

    # Convert issuer-specific booleans / numerics if needed
    for key in ("email_verified", "phone_number_verified"):
        if key in normalized and isinstance(normalized[key], str):
            normalized[key] = normalized[key].lower() in ("true", "1", "yes")

    return normalized


def fetch_federated_user_profile(
    access_token: str,
    issuer: Optional[str] = None,
    client_id: Optional[str] = None,
    timeout: int = 10,
) -> Dict[str, Any]:
    """
    Fetch and normalize federated user profile claims from Auth0 Authentication API.

    Provider-identifying signals:
    - AUTH0_DOMAIN
    - auth0 usersinfo endpoint
    """
    auth0_domain = issuer or os.environ.get("AUTH0_DOMAIN")
    if not auth0_domain:
        raise FederatedLoginError("Missing Auth0 domain. Set AUTH0_DOMAIN or pass issuer.")

    auth0_domain = auth0_domain.replace("https://", "").replace("http://", "").rstrip("/")
    userinfo_url = f"https://{auth0_domain}/userinfo"

    headers = {
        "Authorization": f"Bearer {access_token}",
        "Accept": "application/json",
    }

    response = requests.get(userinfo_url, headers=headers, timeout=timeout)
    if response.status_code != 200:
        raise FederatedLoginError(
            f"Auth0 userinfo request failed: {response.status_code} {response.text}"
        )

    try:
        claims = response.json()
    except ValueError as exc:
        raise FederatedLoginError("Auth0 userinfo response was not valid JSON") from exc

    if not isinstance(claims, dict):
        raise FederatedLoginError("Auth0 userinfo response must be a JSON object")

    normalized = _normalize_claims(claims)

    if client_id:
        normalized.setdefault("audience", client_id)

    return normalized
